### **2. Exact Functions in [`src/uncertainty.js`](file:///c:/Users/Punit%20Raveendran/Desktop/Projects/Drone-DSU/src/uncertainty.js)**

#### **A. Channel Log-Likelihood Ratio (`channelLogLR`)**
* **Location:** [`src/uncertainty.js:84–95`](file:///c:/Users/Punit%20Raveendran/Desktop/Projects/Drone-DSU/src/uncertainty.js#L84-L95)
```javascript
function channelLogLR(reading, trueRate, falseRate) {
  if (reading < NOISE_FLOOR) {
    return Math.log((1 - trueRate) / (1 - falseRate));
  }
  const pGivenSurvivor   = trueRate * reading + (1 - trueRate) * 0.05;
  const pGivenNoSurvivor = falseRate * reading + (1 - falseRate) * 0.05;
  return Math.log(pGivenSurvivor / pGivenNoSurvivor);
}
```

#### **B. Posterior Fusion (`computeConfidence`)**
* **Location:** [`src/uncertainty.js:111–129`](file:///c:/Users/Punit%20Raveendran/Desktop/Projects/Drone-DSU/src/uncertainty.js#L111-L129)
```javascript
export function computeConfidence(readings) {
  const { thermal = 0, audio = 0, camera = 0, gas = 0 } = readings;
  const passive = Math.max(thermal, gas);

  // Start with sparse prior: P(survivor) ≈ 0.10 in disaster rubble (LOG_ODDS_PRIOR = -2.20)
  let logOdds = LOG_ODDS_PRIOR;

  // Camera (YOLOv8): high sensitivity (0.85), low false-positive (0.08)
  logOdds += channelLogLR(camera, 0.85, 0.08);

  // Audio (YAMNet): high sensitivity (0.80), moderate false-positive (0.15)
  logOdds += channelLogLR(audio, 0.80, 0.15);

  // Thermal/Gas (Passive): moderate sensitivity (0.70), high false-positive (0.30)
  logOdds += channelLogLR(passive, 0.70, 0.30);

  // Convert log-odds back to probability [0, 1] via Sigmoid
  return sigmoid(logOdds);
}
```

