61: /**
62:  * Convert log-odds back to probability: 1 / (1 + exp(-x))  (sigmoid)
63:  */
64: function sigmoid(x) {
65:   if (x > 20) return 1.0;
66:   if (x < -20) return 0.0;
67:   return 1.0 / (1.0 + Math.exp(-x));
68: }
