70: /**
71:  * Compute log-likelihood ratio for a single sensor channel.
72:  *
73:  * Models P(reading | survivor) and P(reading | no_survivor) as Beta-like
74:  * distributions calibrated to SAR sensor profiles:
75:  *   - High reading from a survivor channel: strong positive evidence
76:  *   - High reading from only one channel: moderate evidence (could be decoy)
77:  *   - Low reading: weak negative evidence (absence of evidence != evidence of absence)
78:  *
79:  * @param {number} reading   Sensor value in [0, 1]
80:  * @param {number} trueRate  P(high reading | survivor) — channel sensitivity
81:  * @param {number} falseRate P(high reading | no_survivor) — false alarm rate
82:  * @returns {number} log-likelihood ratio
83:  */
84: function channelLogLR(reading, trueRate, falseRate) {
85:   if (reading < NOISE_FLOOR) {
86:     // Below noise floor: weak negative evidence
87:     // LR = P(low | survivor) / P(low | no_survivor) = (1 - trueRate) / (1 - falseRate)
88:     return Math.log((1 - trueRate) / (1 - falseRate));
89:   }
90:   // Above noise floor: evidence scales with reading intensity
91:   // LR increases with reading strength — strong signals are stronger evidence
92:   const pGivenSurvivor   = trueRate * reading + (1 - trueRate) * 0.05;
93:   const pGivenNoSurvivor = falseRate * reading + (1 - falseRate) * 0.05;
94:   return Math.log(pGivenSurvivor / pGivenNoSurvivor);
95: }
