97: /**
98:  * Compute posterior confidence via Bayesian fusion in log-odds space.
99:  *
100:  * Each sensor channel is treated as an independent observation:
101:  *   posterior_log_odds = prior_log_odds + LR_camera + LR_audio + LR_thermal
102:  *
103:  * This correctly compounds independent evidence and naturally handles:
104:  *   - Single hot-debris reading (thermal high, others low) → moderate ~0.25
105:  *   - Two channels confirming (thermal + audio) → candidate ~0.65
106:  *   - All three channels locked → near-certain ~0.92
107:  *
108:  * @param {{ thermal: number, audio: number, camera?: number, gas?: number }} readings
109:  * @returns {number} posterior confidence 0–1
110:  */
111: export function computeConfidence(readings) {
112:   const { thermal = 0, audio = 0, camera = 0, gas = 0 } = readings;
113:   const passive = Math.max(thermal, gas);
114: 
115:   // Start with sparse prior (most cells are empty)
116:   let logOdds = LOG_ODDS_PRIOR;
117: 
118:   // Camera (YOLO): high sensitivity (0.85), low false-positive (0.08)
119:   logOdds += channelLogLR(camera, 0.85, 0.08);
120: 
121:   // Audio (YAMNet): high sensitivity (0.80), moderate false-positive (0.15) — environmental noise
122:   logOdds += channelLogLR(audio, 0.80, 0.15);
123: 
124:   // Thermal/Gas (passive): moderate sensitivity (0.70), high false-positive (0.30) — debris, fires
125:   logOdds += channelLogLR(passive, 0.70, 0.30);
126: 
127:   // Convert back to probability
128:   return sigmoid(logOdds);
129: }
