// Unrescued Target Attraction: gently pull drones toward survivors that still need discovery
// Distributes drones across targets to prevent all clustering on the same one
if (swarmContext.unrescuedTargets && swarmContext.unrescuedTargets.length > 0) {
  const targets = swarmContext.unrescuedTargets.filter(tgt => {
    const tKey = `${tgt.col},${tgt.row}`;
    return !(swarmContext.activeSentinels && swarmContext.activeSentinels.has(tKey));
  });

  if (targets.length > 0) {
    // Distribute drones across targets using ID to prevent all-on-one clustering
    const myTarget = targets[this.id % targets.length];
    const dx = (myTarget.col + 0.5) - this.x;
    const dy = (myTarget.row + 0.5) - this.y;
    const dist = Math.hypot(dx, dy);

    if (dist > 2.5 && dist < 50.0) {
      // Weak long-range pull (doesn't overpower uncertainty gradient exploration)
      // Stronger close-range pull to complete convergence
      const pull = dist < 6.0 ? 0.45 : dist < 15.0 ? 0.18 : 0.08;
      rx += (dx / dist) * pull;
      ry += (dy / dist) * pull;
    }
  }
}

args.TargetContent:
// Unrescued Target Attraction: pull idle drones toward survivors that still need discovery
if (swarmContext.unrescuedTargets && swarmContext.unrescuedTargets.length > 0) {
  let bestDx = 0, bestDy = 0, bestDist = Infinity;
  for (const tgt of swarmContext.unrescuedTargets) {
    const tKey = `${tgt.col},${tgt.row}`;
    const hasSentinel = swarmContext.activeSentinels && swarmContext.activeSentinels.has(tKey);
    if (hasSentinel) continue;
    const dx = (tgt.col + 0.5) - this.x;
    const dy = (tgt.row + 0.5) - this.y;
    const dist = Math.hypot(dx, dy);
    if (dist < bestDist) {
      bestDist = dist;
      bestDx = dx;
      bestDy = dy;
    }
  }
  if (bestDist > 2.5 && bestDist < 50.0) {
    // Distance-scaled pull: stronger when closer, still meaningful at long range
    const pull = bestDist < 8.0 ? 0.55 : bestDist < 20.0 ? 0.40 : 0.25;
    rx += (bestDx / bestDist) * pull;
    ry += (bestDy / bestDist) * pull;
  }
}

