1: /**
2:  * sensors.js — Sensor Generators with Real ML Model Integration (Phase 3)
3:  *
4:  * Generates sensor readings for each cell type in a disaster scenario.
5:  * When the Python ML API server is running, sensor values are based on
6:  * REAL YOLO and YAMNet inference outputs. All values are [0, 1] normalized.
7:  *
8:  * Cell types and their expected sensor profiles:
9:  *   SURVIVOR    → thermal HIGH, audio MEDIUM-HIGH, gas MEDIUM  (all channels active)
10:  *   HOT_DEBRIS  → thermal HIGH, audio LOW,         gas LOW     (thermal false positive)
11:  *   WIND_NOISE  → thermal LOW,  audio HIGH,         gas LOW    (audio false positive)
12:  *   HAZARD      → thermal LOW,  audio LOW,           gas HIGH  (hazard zone)
13:  *   RUBBLE      → all LOW with minor noise
14:  *   CLEAR       → all very LOW
15:  *
16:  * Real Model Integration:
17:  *   - YOLO (human_detector.pt): provides 'camera' channel base values
18:  *   - YAMNet (yamnet_binary_final): provides 'audio' channel base values
19:  *   - Passive Thermal: provides 'thermal' channel base values
20:  */
21: 
22: import { getPINNThermalReading } from './pinn.js';
23: 
24: // Noise parameter — controls how uncertain individual readings look
25: const NOISE_SIGMA = 0.08; // ≈ calibrated to RoboCup Rescue-style sensor variability
26: 
27: /**
28:  * Box-Muller transform for Gaussian noise.
29:  * @param {number} mean
30:  * @param {number} sigma
31:  * @returns {number} sample
32:  */
33: function gaussian(mean, sigma) {
34:   // Box-Muller — fast and adequate for simulation noise
35:   const u1 = Math.random();
36:   const u2 = Math.random();
37:   const z  = Math.sqrt(-2 * Math.log(Math.max(u1, 1e-10))) * Math.cos(2 * Math.PI * u2);
38:   return Math.min(1, Math.max(0, mean + sigma * z));
39: }
40: 
41: /**
42:  * Slow sinusoidal wobble to make readings feel "live" over time.
43:  * @param {number} tick
44:  * @param {number} freq   cycles per 100 ticks
45:  * @param {number} amp    amplitude of wobble
46:  */
47: function wobble(tick, freq = 1.0, amp = 0.05) {
48:   return amp * Math.sin((tick / 100) * freq * 2 * Math.PI);
49: }
50: 
51: // ─── Real ML Model Inference Cache ───────────────────────────────────────────
52: // Fetched from Python API server (/api/inference) at startup.
53: // Contains REAL YOLO and YAMNet outputs for each cell type.
54: 
55: let realModelData = null;
56: let modelFetchAttempted = false;
57: 
58: async function fetchRealModelData() {
59:   if (modelFetchAttempted) return;
60:   modelFetchAttempted = true;
61:   try {
62:     const res = await fetch('/api/inference');
63:     if (res.ok) {
64:       const data = await res.json();
65:       realModelData = data.inference_results;
66:       console.log('🧠 REAL ML MODEL DATA LOADED:', realModelData);
67:       console.log(`   YOLO model: ${data.models.yolo}`);
68:       console.log(`   YAMNet model: ${data.models.yamnet}`);
69:       console.log(`   Formula: ${data.formula}`);
70:     }
71:   } catch (e) {
72:     console.warn('⚠️ ML API server not available — using synthetic sensor profiles.');
73:   }
74: }
75: 
76: // Auto-fetch non-blockingly after module load
77: setTimeout(() => {
78:   fetchRealModelData();
79: }, 50);
80: 
81: /**
82:  * Get real model value for a cell type and channel, with fallback.
83:  */
84: function realValue(cellType, channel, fallback) {
85:   if (!realModelData || !realModelData[cellType]) return fallback;
86:   const d = realModelData[cellType];
87:   if (channel === 'camera') return d.yolo ?? fallback;
88:   if (channel === 'audio') return d.yamnet_human ?? fallback;
89:   if (channel === 'thermal') return d.passive_thermal ?? fallback;
90:   return fallback;
91: }
92: 
93: // ─── Cell-type sensor profiles (using real model outputs when available) ─────
94: 
95: const PROFILES = {
96:   SURVIVOR: (tick) => ({
97:     thermal: gaussian(getPINNThermalReading(true, tick, realValue('SURVIVOR', 'thermal', 0.82)) + wobble(tick, 0.7, 0.04), NOISE_SIGMA),
98:     audio:   gaussian(realValue('SURVIVOR', 'audio', 0.75)   + wobble(tick, 1.3, 0.08), NOISE_SIGMA * 1.2),
99:     camera:  gaussian(realValue('SURVIVOR', 'camera', 0.88)  + wobble(tick, 0.5, 0.05), NOISE_SIGMA * 0.8),
100:     gas:     gaussian(0.45 + wobble(tick, 0.4, 0.03), NOISE_SIGMA),
101:   }),
102: 
103:   HOT_DEBRIS: (tick) => ({
104:     thermal: gaussian(getPINNThermalReading(false, tick, realValue('HOT_DEBRIS', 'thermal', 0.82)) + wobble(tick, 0.3, 0.03), NOISE_SIGMA * 0.7),
105:     audio:   gaussian(realValue('HOT_DEBRIS', 'audio', 0.07),                              NOISE_SIGMA * 0.6),
106:     camera:  gaussian(realValue('HOT_DEBRIS', 'camera', 0.02),                              NOISE_SIGMA * 0.4),
107:     gas:     gaussian(0.12, NOISE_SIGMA * 0.8),
108:   }),
109: 
110:   WIND_NOISE: (tick) => ({
111:     thermal: gaussian(realValue('WIND_NOISE', 'thermal', 0.10),                              NOISE_SIGMA * 0.5),
112:     audio:   gaussian(realValue('WIND_NOISE', 'audio', 0.78)   + wobble(tick, 3.1, 0.15), NOISE_SIGMA * 1.5),
113:     camera:  gaussian(realValue('WIND_NOISE', 'camera', 0.03),                              NOISE_SIGMA * 0.4),
114:     gas:     gaussian(0.08, NOISE_SIGMA * 0.4),
115:   }),
116: 
117:   MANNEQUIN: (tick) => ({
118:     thermal: gaussian(0.10,                            NOISE_SIGMA * 0.5),
119:     audio:   gaussian(0.05,                            NOISE_SIGMA * 0.5),
120:     camera:  gaussian(0.85 + wobble(tick, 0.2, 0.04), NOISE_SIGMA * 0.8),
121:     gas:     gaussian(0.04,                            NOISE_SIGMA * 0.4),
122:   }),
123: 
124:   HAZARD: (tick) => ({
125:     thermal: gaussian(0.18 + wobble(tick, 0.5, 0.02), NOISE_SIGMA),
126:     audio:   gaussian(0.06,                            NOISE_SIGMA * 0.5),
127:     camera:  gaussian(0.02,                            NOISE_SIGMA * 0.4),
128:     gas:     gaussian(0.88 + wobble(tick, 0.2, 0.02), NOISE_SIGMA * 0.6),
129:   }),
130: 
131:   RUBBLE: (_tick) => ({
132:     thermal: gaussian(realValue('EMPTY', 'thermal', 0.18), NOISE_SIGMA * 1.1),
133:     audio:   gaussian(realValue('EMPTY', 'audio', 0.12),   NOISE_SIGMA * 1.3),
134:     camera:  gaussian(realValue('EMPTY', 'camera', 0.05),  NOISE_SIGMA * 1.1),
135:     gas:     gaussian(0.10, NOISE_SIGMA),
136:   }),
137: 
138:   CLEAR: (_tick) => ({
139:     thermal: gaussian(realValue('EMPTY', 'thermal', 0.06), NOISE_SIGMA * 0.5),
140:     audio:   gaussian(realValue('EMPTY', 'audio', 0.05),   NOISE_SIGMA * 0.5),
141:     camera:  gaussian(realValue('EMPTY', 'camera', 0.02),  NOISE_SIGMA * 0.4),
142:     gas:     gaussian(0.04, NOISE_SIGMA * 0.4),
143:   }),
144: };
145: 
146: // ─── SensorGenerator class ───────────────────────────────────────────────────
147: 
148: export class SensorGenerator {
149:   /**
150:    * @param {import('./scenario.js').DisasterScenario} scenario
151:    */
152:   constructor(scenario) {
153:     this.scenario = scenario;
154:   }
155: 
156:   /**
157:    * Get a sensor reading at grid position (col, row) at the given tick.
158:    * Returns null for out-of-bounds cells.
159:    *
160:    * @param {number} col
161:    * @param {number} row
162:    * @param {number} tick
163:    * @returns {{ thermal: number, audio: number, camera: number, gas: number } | null}
164:    */
165:   getSensorAt(col, row, tick) {
166:     const cellType = this.scenario.getCellType(col, row);
167:     if (!cellType) return null;
168: 
169:     const profile = PROFILES[cellType] ?? PROFILES.CLEAR;
170:     return profile(tick);
171:   }
172: 
173:   /**
174:    * Get readings in a local neighborhood (3×3) and return the average.
175:    * Modulates readings by drone approach angle and distance/range (vantage point matters).
176:    *
177:    * @param {number} col
178:    * @param {number} row
179:    * @param {number} tick
180:    * @param {import('./drone.js').Drone} [drone]
181:    * @returns {{ thermal: number, audio: number, camera: number, gas: number, vantageFactor: number }}
182:    */
183:   getLocalReadings(col, row, tick, drone) {
184:     let thermal = 0, audio = 0, camera = 0, gas = 0, count = 0;
185: 
186:     // Calculate drone approach angle & distance modulation factor
187:     let vantageFactor = 1.0;
188:     if (drone) {
189:       const droneHeading = drone.heading || 0;
190:       const dx = (col + 0.5) - drone.x;
191:       const dy = (row + 0.5) - drone.y;
192:       const cellAngle = Math.atan2(dy, dx);
