156:   /**
157:    * Get a sensor reading at grid position (col, row) at the given tick.
158:    * Returns null for out-of-bounds cells.
159:    *
160:    * @param {number} col
161:    * @param {number} row
162:    * @param {number} tick
163:    * @returns {{ thermal: number, audio: number, camera: number, gas: number } | null}
164:    */
165:   getSensorAt(col, row, tick) {
166:     const cellType = this.scenario.getCellType(col, row);
167:     if (!cellType) return null;
168: 
169:     const profile = PROFILES[cellType] ?? PROFILES.CLEAR;
170:     return profile(tick);
171:   }
172: 
173:   /**
174:    * Get readings in a local neighborhood (3×3) and return the average.
175:    * Modulates readings by drone approach angle and distance/range (vantage point matters).
176:    *
177:    * @param {number} col
178:    * @param {number} row
179:    * @param {number} tick
180:    * @param {import('./drone.js').Drone} [drone]
181:    * @returns {{ thermal: number, audio: number, camera: number, gas: number, vantageFactor: number }}
182:    */
183:   getLocalReadings(col, row, tick, drone) {
184:     let thermal = 0, audio = 0, camera = 0, gas = 0, count = 0;
185: 
186:     // Calculate drone approach angle & distance modulation factor
187:     let vantageFactor = 1.0;
188:     if (drone) {
189:       const droneHeading = drone.heading || 0;
190:       const dx = (col + 0.5) - drone.x;
191:       const dy = (row + 0.5) - drone.y;
192:       const cellAngle = Math.atan2(dy, dx);
193:       // Directional factor: sensor sensitivity varies slightly by approach vector
194:       const angleDiff = Math.abs(droneHeading - cellAngle);
195:       const angleFactor = 0.88 + 0.24 * Math.cos(angleDiff);
196:       // Distance/altitude range wobble
197:       const distanceFactor = 0.92 + 0.16 * Math.sin(tick * 0.15 + drone.id);
198:       vantageFactor = angleFactor * distanceFactor;
199:     }
200: 
201:     for (let dc = -1; dc <= 1; dc++) {
202:       for (let dr = -1; dr <= 1; dr++) {
203:         const reading = this.getSensorAt(col + dc, row + dr, tick);
204:         if (!reading) continue;
205:         thermal += reading.thermal;
206:         audio   += reading.audio;
