  // Candidate Proposal: Only propose when genuine multi-modal or high confidence evidence is observed (C >= 0.45),
  // and throttle per sector (max 1 proposal per sector per 50 ticks) to prevent spam at spawn
  if (!this._proposedSectors) this._proposedSectors = new Map();
  const cellKey = `${this.col},${this.row}`;
  const lastProposed = this._proposedSectors.get(cellKey) || -999;

  if (this.confidence >= 0.45 && (tick - lastProposed > 50)) {
    this._proposedSectors.set(cellKey, tick);
    this.lastDebateSpeech = {
      type: 'CANDIDATE_PROPOSAL',
      vote: 'PROPOSAL',
      text: `📢 PROPOSING @ (${this.col},${this.row})`,
      callsign: this.callsign,
      tick,
    };

    this.outbox.push({
      type: 'CANDIDATE_PROPOSAL',
      fromId: this.id,
      callsign: this.callsign,
      col: this.col,
      row: this.row,
      confidence: this.confidence,
      readings: { ...this.lastReadings },
      heading: this._headingAngle,
      tick,
    });
  }

  // Check consensus across ALL candidate sectors this agent has proposed (does not require drone to remain static!)
  if (!this._consensusResolved) this._consensusResolved = new Set();
  for (const [targetKey, votes] of this.votesReceived.entries()) {
    if (this._consensusResolved.has(targetKey)) continue;
    if (votes && votes.length >= 2) {
      const agrees = votes.filter(v => v.vote === 'AGREE').length;
      const rejects = votes.filter(v => v.vote === 'REJECT').length;
      const [tCol, tRow] = targetKey.split(',').map(Number);

      if (agrees >= 2 && agrees >= rejects) {
        this._consensusResolved.add(targetKey);
        this.lastDebateSpeech = {
          type: 'CONSENSUS',
          vote: 'AGREE',
          text: `🏆 CONSENSUS: Confirmed survivor at (${tCol},${tRow})!`,
          callsign: this.callsign,
          tick,
        };
        this.outbox.push({
          type: 'CONSENSUS_CONFIRMED',
          fromId: this.id,
          callsign: this.callsign,
          col: tCol,
          row: tRow,
          agrees,
          rejects,
          tick,
        });
      } else if (rejects >= 2 && rejects > agrees) {
        this._consensusResolved.add(targetKey);
        this.lastDebateSpeech = {
          type: 'CONSENSUS',
          vote: 'REJECT',
          text: `❌ REJECTED: False positive at (${tCol},${tRow})`,
          callsign: this.callsign,
          tick,
        };
        this.outbox.push({
          type: 'CONSENSUS_REJECTED',
          fromId: this.id,
          callsign: this.callsign,
          col: tCol,
          row: tRow,
          agrees,
          rejects,
          tick,
        });
      }
    }
  }
}

/**
 * Process incoming messages from peer agents.
 * Each message is evaluated independently — this agent forms its OWN opinion.
 */
receiveMessages() {
  // Quarantined agents cannot process or participate in consensus
  if (this.isQuarantined) {
    this.inbox = [];
    return;
  }
  // Self-healing: STIGMERGIC mode — skip radio message processing entirely
  if (this.decisionMode === 'STIGMERGIC') {
    this.inbox = [];
    return;
  }
  for (const msg of this.inbox) {
    // Drop messages from untrusted peers (Trust < 0.35)
    const senderTrust = this.getPeerTrust(msg.fromId);
    if (senderTrust < 0.35) continue;

    if (msg.type === 'SECTOR_EXPLORED') {
      // Peer agent informed us that sector (msg.col, msg.row) is already mapped
      this.knownExploredSectors.add(`${msg.col},${msg.row}`);
    } else if (msg.type === 'CANDIDATE_PROPOSAL') {
      // Store peer's observation in our beliefs, weighted by peer trust
      const key = `${msg.col},${msg.row}`;
      if (!this.beliefs.has(key)) {
        this.beliefs.set(key, {
          confidence: msg.confidence * 0.6 * senderTrust,
          readings: msg.readings,
          tick: msg.tick,
          visitCount: 0,
          fromPeer: msg.callsign,
        });
      }
    } else if (msg.type === 'VOTE_REQUEST') {
      // A peer is asking us to vote on a candidate cell
      const key = `${msg.col},${msg.row}`;
      if (!this.votesCast.has(key)) {
        this.votesCast.add(key);
        // Form our OWN opinion based on our current readings at/near this cell
        const dist = Math.hypot(this.col - msg.col, this.row - msg.row);
        let vote = 'ABSTAIN';
        if (dist <= 3.5) {
          const r = this.lastReadings;
          // Multi-channel cross corroboration:
          // Genuine survivor: camera + audio/thermal active
          // Decoy: single-channel spike without corroboration
          const hasMultiModal = (r.camera > 0.22 && (r.thermal > 0.28 || r.audio > 0.28)) ||
                                (r.thermal > 0.42 && r.audio > 0.38);
          const isSingleChannelDecoy = (r.thermal > 0.45 && r.camera < 0.12 && r.audio < 0.12) ||
                                       (r.audio > 0.45 && r.camera < 0.12 && r.thermal < 0.12);

          if (hasMultiModal || this.confidence >= 0.45) {
            vote = 'AGREE';
          } else if (isSingleChannelDecoy || (this.confidence < 0.22 && dist <= 2.0)) {
            vote = 'REJECT';
          } else {
            vote = this.confidence >= 0.35 ? 'AGREE' : 'REJECT';
          }
        }
        if (vote !== 'ABSTAIN') {
          const speechText = vote === 'AGREE' 
            ? `YES! ${(this.confidence * 100).toFixed(0)}% Confirmed` 
            : `NO! ${(this.confidence * 100).toFixed(0)}% Decoy`;

          this.lastDebateSpeech = {
            type: 'VOTE_CAST',
            vote,
            text: speechText,
            callsign: this.callsign,
            tick: msg.tick,
          };

          this.outbox.push({
            type: 'VOTE_CAST',
            fromId: this.id,
            callsign: this.callsign,
            targetCol: msg.col,
            targetRow: msg.row,
            vote,
            confidence: this.confidence,
            heading: this._headingAngle,
            tick: msg.tick,
          });
        }
      }
    } else if (msg.type === 'VOTE_CAST') {
      // Record a vote from a peer agent
      const key = `${msg.targetCol},${msg.targetRow}`;
      if (!this.votesReceived.has(key)) this.votesReceived.set(key, []);
      const votes = this.votesReceived.get(key);
      // Prevent duplicate votes from same agent
      if (!votes.some(v => v.fromId === msg.fromId)) {
        votes.push({
          fromId: msg.fromId,
          callsign: msg.callsign,
          vote: msg.vote,
          confidence: msg.confidence,
          angle: msg.heading,
        });
      }
    }
  }
  this.inbox = []; // clear processed messages
}

